import { ParagraphPlugin, useEditorSelector } from "platejs/react";

/**
 * Subscribe to the current block type at the editor's selection.
 *
 * Must be used inside a `<RichText>` (or `<Plate>`) context.
 *
 * @param editorId - Optional editor ID when multiple editors exist under a `PlateController`
 * @returns The block type string (e.g., `"p"`, `"h1"`, `"h2"`, `"blockquote"`)
 *
 * @example
 * const blockType = useBlockType();
 * const isBlockquote = blockType === BlockquotePlugin.key;
 *
 * @example
 * const blockType = useBlockType();
 * <Select value={blockType} onValueChange={(v) => editor.tf.setNodes({ type: v })} />
 */
export function useBlockType(editorId?: string): string {
  return useEditorSelector(
    (ed) => {
      if (!ed) return ParagraphPlugin.key;
      const blockEntry = ed?.api?.block();
      return blockEntry?.[0]?.type ?? ParagraphPlugin.key;
    },
    [],
    ...(editorId ? [{ id: editorId }] : []),
  );
}
